export function describeInterface(entry, kind, language) {
  const name = entry.signature.match(/(\w+)\s*\(/)?.[1]
  const key = `${entry.owner}.${name}`
  const descriptions = kind === 'signals'
    ? overrides[key] || (entry.owner === 'ETable' ? tableSignals[name] : undefined) || signals[name]
    : methodOverrides[key] || (entry.owner === 'ETable' ? tableMethods[name] : entry.owner === 'ETree' ? treeMethods[name] : undefined) || methods[name]
  if (kind === 'signals' && !descriptions) throw new Error(`Missing signal description: ${key}`)
  return descriptions?.[language === 'zh' ? 0 : 1]
}
